// PostGroupBy groups the rows of a `PostQuery`. Start one with `group_by`.
pub struct PostGroupBy {
	query PostQuery
pub:
	columns    []string
	aggregates []load.Aggregate
}

// group_by groups the matching rows by `columns`. It needs a vgraph driver.
pub fn (q PostQuery) group_by(columns ...string) PostGroupBy {
	return PostGroupBy{
		query:   q
		columns: columns
	}
}

// aggregate adds what each group gets, such as `vgraph.count()` or
// `vgraph.sum('views')`.
pub fn (g PostGroupBy) aggregate(aggregates ...load.Aggregate) PostGroupBy {
	mut all := g.aggregates.clone()
	all << aggregates
	return PostGroupBy{
		...g
		aggregates: all
	}
}

// all returns the groups, ordered by their columns.
pub fn (g PostGroupBy) all() ![]load.Group {
	client, span := g.query.graph.client.start_span(.default, 'query posts', 'posts', 'group_by')
	defer {
		span.end()
	}
	result := PostGroupBy{
		...g
		query: PostQuery{
			...g.query
			graph: Graph{
				client: client
			}
		}
	}.all_untraced() or {
		vgraph.span_failed(span, err)
		return err
	}
	vgraph.span_rows(span, result.len)
	return result
}

// all_untraced is `all`, without its span.
fn (g PostGroupBy) all_untraced() ![]load.Group {
	q := g.query
	return load.group_where(q.graph.client.conn, 'posts', q.graph.client.prepare_query('posts', q.query)!, g.columns.map(load.GroupColumn{
		name: it
		typ:  post_column_type(it)
	}), g.aggregates)
}

// scan reads the groups into `T`, by name: its fields named after the grouped
// columns and the aggregates (`count`, `sum_views`).
pub fn (g PostGroupBy) scan[T]() ![]T {
	return load.scan_groups[T](g.all()!)
}

// post_column_type returns the V type of a column of `posts`.
fn post_column_type(column string) string {
	return match column {
		'Stamps.created_at' { 'time.Time' }
		'Stamps.updated_at' { 'time.Time' }
		'id' { 'i64' }
		'user_id' { 'i64' }
		'body' { 'string' }
		'deleted_at' { '?time.Time' }
		else { '' }
	}
}

// order_by_author_created_at orders the rows by the `Stamps.created_at` of their `author`.
pub fn (q PostQuery) order_by_author_created_at() PostQuery {
	return q.order_by(load.Order{
		expr: '(SELECT "t1"."Stamps.created_at" FROM "users" AS "t1" WHERE "t1"."id" = "t0"."user_id")'
	})
}

