// with_named_comments loads `comments` as `configure` says into
// `named_comments[name]`, besides any other load of it.
pub fn (q PostQuery) with_named_comments(name string, configure ...fn (CommentQuery) CommentQuery) PostQuery {
	mut next := q
	mut named := q.named_comments.clone()
	named[name] = configure
	next.named_comments = named
	return next
}

// with_author loads each row's `author` (many_to_one `users`) with it, in one
// query for all the rows. `configure` narrows them, and can load their edges.
pub fn (q PostQuery) with_author(configure ...fn (UserQuery) UserQuery) PostQuery {
	mut next := q
	next.with_author = true
	next.author_fns = configure
	return next
}

// with_comments loads each row's `comments` (one_to_many `comments`) with it, in one
// query for all the rows. `configure` narrows them, and can load their edges.
pub fn (q PostQuery) with_comments(configure ...fn (CommentQuery) CommentQuery) PostQuery {
	mut next := q
	next.with_comments = true
	next.comments_fns = configure
	return next
}

// all returns the matching rows, with the requested edges.
pub fn (q PostQuery) all() ![]PostNode {
	client, span := q.graph.client.start_span(.default, 'query posts', 'posts', 'all')
	defer {
		span.end()
	}
	result := PostQuery{
		...q
		graph: Graph{
			client: client
		}
	}.all_untraced() or {
		vgraph.span_failed(span, err)
		return err
	}
	vgraph.span_rows(span, result.len)
	return result
}

// all_untraced is `all`, without its span.
fn (q PostQuery) all_untraced() ![]PostNode {
	rows := load.select_where[models.Post](q.graph.client.conn, q.graph.client.prepare_query('posts', q.query)!)!
	return q.nodes(rows)
}

// first returns the first matching row, with the requested edges, or a
// `NotFoundError`.
pub fn (q PostQuery) first() !PostNode {
	nodes := q.limit(1).all()!
	if nodes.len == 0 {
		return NotFoundError{
			table: 'posts'
		}
	}
	return nodes[0]
}

// nodes loads the requested edges onto `rows`, which the caller already has: one
// query per edge, however many rows there are.
pub fn (q PostQuery) nodes(rows []models.Post) ![]PostNode {
	mut nodes := rows.map(PostNode{
		graph: q.graph
		post:  it
	})
	if q.with_author {
		found := q.load_author(rows, q.author_fns)!
		for mut node in nodes {
			// at most one each: the first, in the order of the query
			list := found[node.post.id.str()] or { [] }
			if list.len > 0 {
				node.author = &UserNode{
					...list[0]
				}
			}
			node.loaded << 'author'
		}
	}
	if q.with_comments {
		found := q.load_comments(rows, q.comments_fns)!
		for mut node in nodes {
			node.comments = found[node.post.id.str()] or { [] }
			node.loaded << 'comments'
		}
	}
	for name, fns in q.named_comments {
		found := q.load_comments(rows, fns)!
		for mut node in nodes {
			node.named_comments[name] = found[node.post.id.str()] or { [] }
		}
	}
	return nodes
}

// load_author loads the `author` of `rows`, keyed by each row's key.
fn (q PostQuery) load_author(rows []models.Post, fns []fn (UserQuery) UserQuery) !map[string][]UserNode {
	client, span := q.graph.client.start_load_span(.default, 'posts', 'author', rows.len)
	defer {
		span.end()
	}
	result := PostQuery{
		...q
		graph: Graph{
			client: client
		}
	}.load_author_untraced(rows, fns) or {
		vgraph.span_failed(span, err)
		return err
	}
	return result
}

// load_author_untraced is `load_author`, without its span.
fn (q PostQuery) load_author_untraced(rows []models.Post, fns []fn (UserQuery) UserQuery) !map[string][]UserNode {
	mut sub := q.graph.users()
	for configure in fns {
		sub = configure(sub)
	}
	mut keys := []string{}
	for row in rows {
		keys << row.user_id.str()
	}
	targets := sub.nodes(load.select_in[models.User](q.graph.client.conn, 'id', load.unique(keys),
		query: q.graph.client.prepare_edge_query('users', sub.query)!
	)!)!
	mut by_key := map[string]UserNode{}
	for target in targets {
		by_key[target.user.id.str()] = target
	}
	mut found := map[string][]UserNode{}
	for row in rows {
		if target := by_key[row.user_id.str()] {
			found[row.id.str()] = [target]
		}
	}
	return found
}

// author_or_err returns the `author`: a `NotLoadedError` when the query didn't
// load it, a `NotFoundError` when the row has none.
pub fn (n PostNode) author_or_err() !&UserNode {
	if 'author' !in n.loaded {
		return NotLoadedError{
			edge: 'posts.author'
		}
	}
	if target := n.author {
		return target
	}
	return NotFoundError{
		table: 'users'
	}
}

// load_comments loads the `comments` of `rows`, keyed by each row's key.
fn (q PostQuery) load_comments(rows []models.Post, fns []fn (CommentQuery) CommentQuery) !map[string][]CommentNode {
	client, span := q.graph.client.start_load_span(.default, 'posts', 'comments', rows.len)
	defer {
		span.end()
	}
	result := PostQuery{
		...q
		graph: Graph{
			client: client
		}
	}.load_comments_untraced(rows, fns) or {
		vgraph.span_failed(span, err)
		return err
	}
	return result
}

// load_comments_untraced is `load_comments`, without its span.
fn (q PostQuery) load_comments_untraced(rows []models.Post, fns []fn (CommentQuery) CommentQuery) !map[string][]CommentNode {
	mut sub := q.graph.comments()
	for configure in fns {
		sub = configure(sub)
	}
	children := sub.nodes(load.select_each[models.Comment](q.graph.client.conn, 'owner_id',
		rows.map(it.id.str()),
		type_col: 'owner_type'
		type_val: 'Post'
		soft_del: 'deleted_at'
		query:    q.graph.client.prepare_edge_query('comments', sub.query)!
	)!)!
	mut by_parent := map[string][]CommentNode{}
	for child in children {
		by_parent[child.comment.owner_id.str()] << child
	}
	return by_parent
}

// comments_or_err returns the `comments`, or a `NotLoadedError` when the query
// didn't load them.
pub fn (n PostNode) comments_or_err() ![]CommentNode {
	if 'comments' !in n.loaded {
		return NotLoadedError{
			edge: 'posts.comments'
		}
	}
	return n.comments
}

// query_author starts a query of this row's `author`, which matches
// nothing when the row has none.
pub fn (n PostNode) query_author() UserQuery {
	key := n.post.user_id
	return n.graph.users().where(load.eq('id', key))
}

// query_comments starts a query of this row's `comments`.
pub fn (n PostNode) query_comments() CommentQuery {
	return n.graph.comments().where(load.eq('owner_id', n.post.id), load.eq('owner_type', 'Post'), load.is_null('deleted_at'))
}
